  "sql": "WITH _base AS (\n  SELECT\n    customers__regions.name AS \"orders.customers.regions.name\",\n    CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.revenue\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  LEFT JOIN regions AS customers__regions\n    ON customers.region_id = customers__regions.id\n  WHERE\n    CASE\n      WHEN customers.tags IS NULL OR 'vip' IS NULL\n      THEN NULL\n      ELSE LIST_CONTAINS([__slayer_e FOR __slayer_e IN customers.tags IF __slayer_e IS NOT NULL], 'vip')\n    END\n  GROUP BY\n    customers__regions.name\n), _cm_orders__amount_sum_partition_by AS (\n  SELECT\n    CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.amount_sum_partition_by\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  WHERE\n    CASE\n      WHEN customers.tags IS NULL OR 'vip' IS NULL\n      THEN NULL\n      ELSE LIST_CONTAINS([__slayer_e FOR __slayer_e IN customers.tags IF __slayer_e IS NOT NULL], 'vip')\n    END\n)\nSELECT\n  _base.\"orders.customers.regions.name\",\n  _base.\"orders.revenue\",\n  _base.\"orders.revenue\" / NULLIF(_cm_orders__amount_sum_partition_by.\"orders.amount_sum_partition_by\", 0) AS \"orders.share\"\nFROM _base\nCROSS JOIN _cm_orders__amount_sum_partition_by\nORDER BY\n  _base.\"orders.customers.regions.name\" ASC\nLIMIT 101"
}
